const {is_palindrome} = require('./solution');
const assert = require('assert');

function testIsPalindrome() {
    assert.strictEqual(is_palindrome('A man, a plan, a canal: Panama'), true);
    assert.strictEqual(is_palindrome('race a car'), false);
    assert.strictEqual(is_palindrome(' '), true);  // Empty string is considered as palindrome.
}
testIsPalindrome();

